// ——— 입력 검증 + 변수 설정 + 고유 requestId 생성 ———
const body = $input.first().json.body || $input.first().json;

const diagnosisId = body.diagnosisId;
const url = body.url;

// 필수 파라미터 검증
if (!diagnosisId || typeof diagnosisId !== 'string') {
  throw new Error(`Invalid diagnosisId: ${diagnosisId}`);
}
if (!url || typeof url !== 'string' || !url.startsWith('http')) {
  throw new Error(`Invalid URL: ${url}`);
}

// 고유 requestId 생성 (멱등성 키로 사용)
const requestId = `${diagnosisId}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

return [{
  json: {
    diagnosisId,
    url,
    requestId,
    startedAt: new Date().toISOString(),
  }
}];

// ——— Normalize: 각 소스의 결과를 CrawlData 구조로 조합 ———
// v3.1 변경: crawlStatus 필드 추가 (Firecrawl 필수 + completeness 기반)

const getNodeResult = (nodeName) => {
  try {
    const result = $(nodeName).first()?.json ?? null;
    if (result && (result.error || result.code === 'ERR_' || result.statusCode >= 400)) {
      return { _error: true, _nodeName: nodeName, ...result };
    }
    return result;
  } catch (e) {
    return { _error: true, _nodeName: nodeName, _message: e.message };
  }
};

const vars = $('Validate & Set Variables').first().json;
const startedAt = new Date(vars.startedAt);
const completedAt = new Date();
const durationMs = completedAt - startedAt;

// Group A: Firecrawl
const scrape = getNodeResult('A1: Firecrawl Scrape');
const map = getNodeResult('A2: Firecrawl Map');

// Group B: Performance + Security
const psMobile = getNodeResult('B1: PageSpeed Mobile');
const psDesktop = getNodeResult('B2: PageSpeed Desktop');
const ssl = getNodeResult('B3: SSL Labs');
const obs = getNodeResult('B4: Observatory v2');

// Group C: Basic fetch
const robots = getNodeResult('C1: robots.txt');
const sitemap = getNodeResult('C2: sitemap.xml');
const llms = getNodeResult('C3: llms.txt');
const llmsFull = getNodeResult('C4: llms-full.txt');

// dataCompleteness 계산
const sources = [
  { name: 'firecrawl_scrape', ok: !!scrape && !scrape._error && !scrape.error },
  { name: 'firecrawl_map', ok: !!map && !map._error && !map.error },
  { name: 'pagespeed_mobile', ok: !!psMobile && !psMobile._error && !psMobile.error },
  { name: 'pagespeed_desktop', ok: !!psDesktop && !psDesktop._error && !psDesktop.error },
  { name: 'ssl_labs', ok: !!ssl && !ssl._error && !ssl.error },
  { name: 'observatory', ok: !!obs && !obs._error && !obs.error },
  { name: 'robots_txt', ok: !!robots && !robots._error && (robots.statusCode === undefined || robots.statusCode < 400) },
  { name: 'sitemap_xml', ok: !!sitemap && !sitemap._error && (sitemap.statusCode === undefined || sitemap.statusCode < 400) },
  { name: 'llms_txt', ok: !!llms && !llms._error && (llms.statusCode === undefined || llms.statusCode < 400) },
];

const successCount = sources.filter(s => s.ok).length;
const dataCompleteness = Math.round((successCount / sources.length) * 100);

// v3.1 신규: crawlStatus 결정 로직
// - firecrawl_scrape 필수 (메인 콘텐츠 없으면 진단 무의미)
// - completeness 기준으로 success/partial 분기
// - firecrawl 실패 또는 매우 낮은 completeness면 quality_rejected
const firecrawlOk = sources.find(s => s.name === 'firecrawl_scrape')?.ok || false;
let crawlStatus;
if (!firecrawlOk) {
  crawlStatus = 'quality_rejected'; // 메인 콘텐츠 없음 → 분석 불가
} else if (dataCompleteness >= 70) {
  crawlStatus = 'success';
} else if (dataCompleteness >= 30) {
  crawlStatus = 'partial'; // 일부 데이터 부족하지만 분석 가능
} else {
  crawlStatus = 'quality_rejected'; // 너무 부족
}

// 실패한 소스의 에러 상세 기록
const errorDetails = sources.filter(s => !s.ok).map(s => {
  const nodeResult = { firecrawl_scrape: scrape, firecrawl_map: map, pagespeed_mobile: psMobile, pagespeed_desktop: psDesktop, ssl_labs: ssl, observatory: obs, robots_txt: robots, sitemap_xml: sitemap, llms_txt: llms }[s.name];
  // v3.5 fix: error는 string이어야 함 (Next.js Zod schema 검증). 객체면 JSON.stringify.
  const rawErr = nodeResult?._message || nodeResult?.error || nodeResult?.message || `HTTP ${nodeResult?.statusCode || 'unknown'}`;
  let errStr;
  if (typeof rawErr === 'string') {
    errStr = rawErr;
  } else if (rawErr === null || rawErr === undefined) {
    errStr = 'unknown error';
  } else {
    try { errStr = JSON.stringify(rawErr); } catch (e) { errStr = String(rawErr); }
  }
  return {
    source: s.name,
    error: errStr,
  };
});

return [{
  json: {
    diagnosisId: vars.diagnosisId,
    url: vars.url,
    requestId: vars.requestId,
    crawlStatus,
    dataCompleteness,
    durationMs,
    durationSec: Math.round(durationMs / 1000),
    successSources: sources.filter(s => s.ok).map(s => s.name),
    failedSources: sources.filter(s => !s.ok).map(s => s.name),
    errorDetails,
    crawlResult: {
      firecrawl_scrape: scrape,
      firecrawl_map: map,
      pagespeed_mobile: psMobile,
      pagespeed_desktop: psDesktop,
      ssl_labs: ssl,
      observatory: obs,
      robots_txt: robots,
      sitemap_xml: sitemap,
      llms_txt: llms,
      llms_full_txt: llmsFull,
    },
    crawled_at: completedAt.toISOString(),
  }
}];

// ——— 콜백 결과 검증 ———
// v3.1: fullResponse:true 적용으로 statusCode 정상 추출 가능
const callbackResult = $input.first().json;
const vars = $('Validate & Set Variables').first().json;
const normalizedData = $('Normalize Results').first().json;

// 콜백 성공 여부 판별
const statusCode = callbackResult?.statusCode || callbackResult?.headers?.[':status'] || 0;
const isSuccess = statusCode >= 200 && statusCode < 400;

// 308 redirect 감지 (learnings #12 — trailing slash 문제)
const isRedirect = statusCode === 308 || statusCode === 301 || statusCode === 302;

return [{
  json: {
    diagnosisId: vars.diagnosisId,
    url: vars.url,
    requestId: vars.requestId,
    callbackSuccess: isSuccess,
    callbackRedirect: isRedirect,
    callbackStatusCode: statusCode || 'unknown',
    callbackError: callbackResult?.error || null,
    crawlStatus: normalizedData.crawlStatus,
    dataCompleteness: normalizedData.dataCompleteness,
    durationSec: normalizedData.durationSec,
    failedSources: normalizedData.failedSources,
    errorDetails: normalizedData.errorDetails,
    executionId: $execution.id,
    timestamp: new Date().toISOString(),
  }
}];

// ——— 성공 로그 ———
const data = $input.first().json;
console.log(`✅ Crawl SUCCESS: diagnosisId=${data.diagnosisId}, status=${data.crawlStatus}, completeness=${data.dataCompleteness}%, duration=${data.durationSec}s, failed=[${data.failedSources.join(',')}]`);
return [$input.first()];

// ——— 콜백 실패 에러 알림 생성 ———
// v3.1: Monitor v2가 30분마다 자동 감지하지만, 즉시 발생 알림도 유지
const data = $input.first().json;
const errorMsg = [
  `🚨 CALLBACK FAILED`,
  `DiagnosisId: ${data.diagnosisId}`,
  `URL: ${data.url}`,
  `Callback Status: ${data.callbackStatusCode}`,
  `Redirect Detected: ${data.callbackRedirect}`,
  `Error: ${JSON.stringify(data.callbackError)}`,
  `Crawl Status: ${data.crawlStatus}`,
  `Completeness: ${data.dataCompleteness}%`,
  `Duration: ${data.durationSec}s`,
  `Execution: ${data.executionId}`,
  `Time: ${data.timestamp}`,
].join('\n');

console.error(errorMsg);

return [{
  json: {
    ...data,
    alertType: 'callback_failed',
    alertMessage: errorMsg,
  }
}];

// ——— 데이터 품질 부족 로그 ———
// v3.1: Fail Callback이 별도로 발송되므로 여기는 로그만
const data = $('Normalize Results').first().json;
const vars = $('Validate & Set Variables').first().json;

const errorMsg = [
  `⚠️ QUALITY REJECTED — Fail callback sent`,
  `DiagnosisId: ${vars.diagnosisId}`,
  `URL: ${vars.url}`,
  `Crawl Status: ${data.crawlStatus}`,
  `Completeness: ${data.dataCompleteness}%`,
  `Failed Sources: ${data.failedSources.join(', ')}`,
  `Error Details:`,
  ...data.errorDetails.map(e => `  - ${e.source}: ${e.error}`),
  `Duration: ${data.durationSec}s`,
  `Execution: ${$execution.id}`,
].join('\n');

console.error(errorMsg);

return [{
  json: {
    diagnosisId: vars.diagnosisId,
    url: vars.url,
    alertType: 'low_quality',
    alertMessage: errorMsg,
    crawlStatus: data.crawlStatus,
    dataCompleteness: data.dataCompleteness,
    failedSources: data.failedSources,
    errorDetails: data.errorDetails,
    executionId: $execution.id,
    timestamp: new Date().toISOString(),
  }
}];
